	private static function is_onboarding() {
		if ( ! is_user_logged_in() ) {
			return false;
		}
		if ( ! isset( $_GET['action'] ) || sanitize_key( wp_unslash( $_GET['action'] ) ) !== 'create' ) {
			return false;
		}
		global $wpdb;
		$count = (int) $wpdb->get_var( $wpdb->prepare(
			"SELECT COUNT(*) FROM `{$wpdb->prefix}ps_pets` WHERE user_id = %d AND status = 'active'",
			get_current_user_id()
		) );
		return $count === 0;
	}

	public static function body_class( $classes ) {
		if ( false !== get_query_var( self::ENDPOINT, false ) && self::is_onboarding() ) {
			$classes[] = 'ps-pet-onboarding';
		}
		return $classes;
	}

